/* Renders conferences.html from window.CONFERENCES (generated by scripts/update_conferences.py). */
document.addEventListener("DOMContentLoaded", function () {
  var data = window.CONFERENCES;
  var openEl = document.getElementById("conf-open");
  var closedEl = document.getElementById("conf-closed");
  if (!data || !openEl) return;

  var LABELS = { ai: "AI & ML", security: "IoT & Cyber Security", comm: "Communications & Networking" };
  var state = { cat: "", q: "" };
  var now = new Date();

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  function fmtLocal(iso) {
    var d = new Date(iso);
    return d.toLocaleString(undefined, { day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
  }

  function countdown(iso) {
    var ms = new Date(iso) - now;
    var days = Math.floor(ms / 86400000);
    if (days >= 1) return days + (days === 1 ? " day left" : " days left");
    var hours = Math.max(0, Math.floor(ms / 3600000));
    return hours + (hours === 1 ? " hour left" : " hours left");
  }

  function urgency(iso) {
    var days = (new Date(iso) - now) / 86400000;
    return days <= 14 ? "soon" : days <= 45 ? "near" : "far";
  }

  function matches(c) {
    if (state.cat && c.category !== state.cat) return false;
    if (!state.q) return true;
    var hay = (c.name + " " + c.full + " " + c.place).toLowerCase();
    return hay.indexOf(state.q) >= 0;
  }

  function card(c, open) {
    var title = esc(c.name) + " " + esc(c.year);
    var head = c.link
      ? '<a href="' + esc(c.link) + '" target="_blank" rel="noopener">' + title + "</a>"
      : title;
    var dl;
    if (open && c.deadline) {
      dl = '<div class="conf-deadline ' + urgency(c.deadline) + '">' +
        '<span class="conf-count">' + countdown(c.deadline) + "</span>" +
        '<span class="conf-dl-date">Paper deadline: ' + fmtLocal(c.deadline) + " <span class=\"meta\">(your time)</span></span>" +
        (c.abstract ? '<span class="conf-dl-date">Abstract: ' + fmtLocal(c.abstract) + "</span>" : "") +
        "</div>";
    } else if (open) {
      dl = '<div class="conf-deadline tba"><span class="conf-count">Deadline TBA</span></div>';
    } else {
      dl = '<div class="conf-deadline closed"><span class="conf-count">Submission closed</span></div>';
    }
    return '<div class="card conf-card" data-cat="' + esc(c.category) + '">' +
      '<div class="conf-top">' +
        '<div class="conf-title"><h3>' + head + "</h3>" +
          '<div class="conf-full">' + esc(c.full) + "</div></div>" +
        '<div class="conf-badges">' +
          '<span class="conf-cat" data-cat="' + esc(c.category) + '">' + LABELS[c.category] + "</span>" +
          (c.core ? '<span class="conf-rank" title="CORE ranking">CORE ' + esc(c.core) + "</span>" : "") +
        "</div>" +
      "</div>" +
      '<div class="conf-meta">' +
        "<span>📅 " + esc(c.date || "TBA") + "</span>" +
        "<span>📍 " + esc(c.place || "TBA") + "</span>" +
      "</div>" +
      dl +
      (c.note ? '<div class="conf-note">' + esc(c.note) + "</div>" : "") +
      "</div>";
  }

  function render() {
    var items = data.items.filter(matches);
    var open = items.filter(function (c) { return c.open; }).sort(function (a, b) {
      if (!a.deadline) return 1;
      if (!b.deadline) return -1;
      return a.deadline < b.deadline ? -1 : 1;
    });
    var closed = items.filter(function (c) { return !c.open; }).sort(function (a, b) {
      return (a.year - b.year) || (a.deadline < b.deadline ? -1 : 1);
    });
    openEl.innerHTML = open.length ? open.map(function (c) { return card(c, true); }).join("")
      : '<p class="meta">No open calls match your filter.</p>';
    closedEl.innerHTML = closed.length ? closed.map(function (c) { return card(c, false); }).join("")
      : '<p class="meta">Nothing here for this filter.</p>';
    document.getElementById("conf-open-count").textContent = open.length;
    document.getElementById("conf-closed-count").textContent = closed.length;
  }

  var filters = document.getElementById("conf-filters");
  filters.innerHTML = ['<button class="chip-btn" data-filter="" aria-pressed="true">All</button>']
    .concat(Object.keys(LABELS).map(function (k) {
      return '<button class="chip-btn" data-filter="' + k + '" aria-pressed="false">' + LABELS[k] + "</button>";
    })).join("");
  filters.addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-filter]");
    if (!btn) return;
    filters.querySelectorAll("button").forEach(function (b) {
      b.setAttribute("aria-pressed", b === btn ? "true" : "false");
    });
    state.cat = btn.getAttribute("data-filter");
    render();
  });

  document.getElementById("conf-search").addEventListener("input", function (e) {
    state.q = e.target.value.trim().toLowerCase();
    render();
  });

  document.getElementById("conf-updated").textContent = data.updated;
  var openAll = data.items.filter(function (c) { return c.open; });
  var soon = openAll.filter(function (c) { return c.deadline && (new Date(c.deadline) - now) / 86400000 <= 30; });
  var setStat = function (id, n) { var el = document.getElementById(id); if (el) el.textContent = n; };
  setStat("conf-stat-open", openAll.length);
  setStat("conf-stat-soon", soon.length);
  setStat("conf-stat-total", data.items.length);
  render();
});
